WITH
english_countries AS (
    SELECT DISTINCT CountryCode FROM countrylanguage WHERE Language = 'English'
),
dutch_countries AS (
    SELECT DISTINCT CountryCode FROM countrylanguage WHERE Language = 'Dutch'
),
both_languages AS (
    SELECT CountryCode FROM english_countries
    INTERSECT
    SELECT CountryCode FROM dutch_countries
)
SELECT COUNT(*) AS num_countries_with_english_and_dutch FROM both_languages;

SELECT CountryCode, MAX(Percentage) AS MaxPercentage
FROM countrylanguage
GROUP BY CountryCode;
